// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const [input, setInput] =
    useState("");

  const [messages, setMessages] =
    useState([
      {
        user: "AI",
        type: "ai",
        text:
          "안녕하세요 🙂 오늘은 가장 인상 깊었던 장면을 이야기해볼게요.",
      },

      {
        user: "민지",
        type: "other",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        text:
          "와타나베의 감정선이 정말 좋았어요.",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "좋아요 ✨ 모두가 공감했던 장면이 있었네요.",
      },
    ]);

  const sendMessage = () => {
    if (!input.trim()) return;

    const newMessage = {
      user: "나",
      type: "me",
      text: input,
    };

    setMessages([
      ...messages,
      newMessage,
    ]);

    setInput("");
  };

  return (
    <div className="meeting-page">
      {/* 상단 */}

      <div className="meeting-header">
        <div className="meeting-room-name">
          📚 {roomTitle}
        </div>
      </div>

      {/* 채팅 */}

      <div className="meeting-chat-area">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-row ${
              msg.type === "me"
                ? "right"
                : "left"
            }`}
          >
            {msg.type !== "me" && (
              <div className="chat-profile">
                {msg.user[0]}
              </div>
            )}

            <div>
              {msg.type !== "me" && (
                <div className="chat-name">
                  {msg.user}
                </div>
              )}

              <div
                className={`chat-bubble ${
                  msg.type === "me"
                    ? "user-chat"
                    : "ai-chat"
                }`}
              >
                {msg.text}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* 입력 */}

      <div className="meeting-input-wrap">
        <input
          value={input}
          onChange={(e) =>
            setInput(e.target.value)
          }
          placeholder="생각을 입력해보세요"
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              sendMessage();
            }
          }}
        />

        <button onClick={sendMessage}>
          전송
        </button>
      </div>
    </div>
  );
}

export default MeetingRoom;
